/* بيانات باب ttw: تُحمَّل عند أول فتح للقسم */
window.TTW = {"ch":[{"id":"tatawwu","t":"التطوع بالخير","d":"الآيات التي ورد فيها لفظ التطوع بالخير: «فمن تطوع خيراً»، ووصف المطوعين من المؤمنين في الصدقات، وما جاء في فعل الخير عموماً وأن الله يعلمه ولن يُكفر."},{"id":"musaraa","t":"المسارعة إلى الخيرات والاستباق","d":"الآيات التي أمرت بالمسارعة إلى المغفرة والجنة والاستباق إلى الخيرات، ووصفت الأنبياء والمؤمنين بأنهم يسارعون في الخيرات، وذكرت السابقين بالخيرات."},{"id":"tawun","t":"التعاون والأخوّة والتواصي","d":"الآيات التي جعلت المؤمنين إخوة وصفّاً مرصوصاً، وأمرت بالاعتصام وترك التفرق، ونهت عن التعاون على الإثم والعدوان، وذكرت التواصي بالحق والصبر والمرحمة، والإعانة في الخير بين الأخوين وفي مصلحة الجماعة."},{"id":"umma","t":"الأمة الداعية إلى الخير والأمر بالمعروف","d":"الآيات التي ذكرت أمة تدعو إلى الخير وتأمر بالمعروف وتنهى عن المنكر، وخيرية هذه الأمة، والدعوة إلى الله قولاً وعملاً، وبقية أهل الإصلاح، وذمّ ترك التناهي عن المنكر."},{"id":"imara","t":"عمارة المساجد وسقاية الحاج","d":"الآيات التي ذكرت من يعمر مساجد الله، وسقاية الحاج وعمارة المسجد الحرام، ومن إذا مكّنهم الله في الأرض أقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف."}],"tp":[{"id":"tatawwa","ch":"tatawwu","t":"«فمن تطوع خيراً»","e":"ورود لفظ التطوع بالخير في الحج والصيام، وبيان أن الله شاكر عليم.","ay":[[2,158,158],[2,184,184]],"q":[{"bk":"saadi","s":2,"ay":158,"x":"وقوله:{ومن تطوع}؛ أي: فعل طاعة مخلصاً بها لله تعالى {خيراً}؛ من حج وعمرة وطواف وصلاة وصوم وغير ذلك، فهو خير له؛ فدل هذا على أنه كلما ازداد العبد من طاعة الله ازداد خيره وكماله ودرجته عند الله لزيادة إيمانه، ودل تقييد التطوع بالخير أن من تطوع بالبدع التي لم يشرعها الله ولا رسوله أنه لا يحصل له إلا العناء، وليس بخير له، بل قد يكون شرًّا له إن كان متعمداً عالماً لعدم مشروعية العمل. {فإن الله شاكر عليم}؛ الشاكر والشكور من أسماء الله تعالى الذي يقبل من عباده اليسير من العمل …","w":"السعدي","en":"\"And whoever volunteers\" — that is, does an act of obedience sincerely for Allah — \"good\", of Hajj, Umra, tawaf, prayer, fasting and the like, it is better for him. This shows that the more a servant increases in obedience to Allah, the more his good, his perfection and his rank with Allah increase, through the increase of his faith. And the qualification of volunteering by \"good\" shows that whoever volunteers by innovations that Allah and His Messenger have not legislated gains nothing but toil, and it is not good for him; indeed it may be evil for him if he does it deliberately, knowing that the act is not legislated. \"Then indeed Allah is Appreciative, Knowing\": the Appreciative, al-Shakir and al-Shakur, is among the names of Allah, who accepts from His servants the little they do …"},{"bk":"saadi","s":2,"ay":184,"x":"وفيه تنشيط لهذه الأمة بأنه ينبغي لكم أن تنافسوا غيركم في تكميل الأعمال والمسارعة إلى صالح الخصال، وأنه ليس من الأمور الثقيلة التي اختصَّيتم بها.","w":"السعدي","en":"And in it is an encouragement to this community that it should compete with others in perfecting deeds and hastening to good qualities, and that it is not among the heavy matters that you alone were singled out with."}],"h":["tatawwuh"]},{"id":"mutawwiin","ch":"tatawwu","t":"«الذين يلمزون المطوعين من المؤمنين في الصدقات»","e":"وصف المؤمنين الذين يتطوعون بالصدقات، وما قاله المنافقون فيهم.","ay":[[9,79,79]],"q":[{"bk":"saadi","s":9,"ay":79,"x":"ومنها: أنَّ من أطاع الله وتطوَّع بخَصْلةٍ من خصال الخير؛ فإنَّ الذي ينبغي إعانته وتنشيطه على عمله، وهؤلاء قصدوا تثبيطهم بما قالوا فيهم، وعابوهم عليه.","w":"السعدي","en":"Among them: that whoever obeys Allah and volunteers some good quality should be helped and encouraged in his work, whereas these people meant to discourage them by what they said about them, and faulted them for it."},{"bk":"saadi","s":9,"ay":79,"x":"كلامٌ مقصوده باطلٌ؛ فإنَّ الله غنيٌ عن صدقة المتصدِّق بالقليل والكثير، بل وغني عن أهل السماوات والأرض، ولكنه تعالى أمر العباد بما هم مفتقرون إليه؛ فالله وإن كان غنيًّا عنه؛ فهم فقراء إليه؛ {فمن يعملۡ مثقال ذرَّةٍ خيراً يره}، وفي هذا القول من التثبيط عن الخير ما هو ظاهرٌ بيّن، ولهذا كان جزاؤهم أن يسخر الله منهم، {ولهم عذابٌ أليمٌ}.","w":"السعدي","en":"A statement whose aim is false; for Allah is free of need of the charity of the giver, whether small or great, indeed free of need of the inhabitants of the heavens and the earth. But He commanded His servants with what they themselves need; so although Allah is free of need of it, they are in need of Him: \"so whoever does an atom's weight of good will see it\". And in this saying there is plainly a discouragement from good, which is why their recompense is that Allah mocks them, \"and for them is a painful punishment\"."}],"h":[]},{"id":"khayr","ch":"tatawwu","t":"«وما تفعلوا من خير يعلمه الله» و«فلن يكفروه»","e":"عموم قوله «وما تفعلوا من خير يعلمه الله» وأن ما فُعل من خير لن يُكفر.","ay":[[2,197,197],[3,115,115]],"q":[{"bk":"saadi","s":2,"ay":197,"x":"واعلم أنه لا يتم التقرب إلى الله بترك المعاصي حتى يفعل الأوامر، ولهذا قال تعالى:{وما تفعلوا من خير يعلمه الله}؛ أتى بمن لتنصيص العموم فكل خير وقربة وعبادة داخل في ذلك، أي: فإن الله به عليم، وهذا يتضمن غاية الحث على أفعال الخير خصوصاً في تلك البقاع الشريفة والحرمات المنيفة، فإنه ينبغي تدارك ما أمكن تداركه فيها من صلاة وصيام وصدقة وطواف وإحسان قولي وفعلي، ثم أمر تعالى بالتزود لهذا السفر المبارك؛ فإن التزود فيه الاستغناء عن المخلوقين، والكف عن أموالهم سؤالاً واستشرافاً، وفي الإكثار منه نفع، وإعانة للمسافرين، وزيادة قربة لرب العالمين، وهذا الزاد الذي المراد منه إقامة البِنْية بُلْغَةٌ ومتاع، وأما الزاد الحقيقي المستمر نفعه لصاحبه في دنياه وأخراه فهو زاد التقوى؛ الذي هو زاد إلى دار القرار …","w":"السعدي","en":"And know that drawing near to Allah is not complete by leaving sins until one does what is commanded. Hence He said: \"And whatever good you do, Allah knows it\" — He used \"min\" to make the generality explicit, so every good, act of nearness and act of worship is included, meaning that Allah is aware of it. This contains the utmost urging to deeds of good, especially in those noble places and lofty sanctities, where one should make up what can be made up, of prayer, fasting, charity, tawaf and kindness in word and deed. Then He commanded taking provision for this blessed journey; for taking provision in it frees one from needing creatures and from restraining one's hand from their wealth, asking or looking toward it, and in having much of it there is benefit, help for travellers and added nearness to the Lord of the worlds. This provision, whose aim is to sustain the body, is a means and a passing enjoyment; but the real provision whose benefit continues for its owner in this world and the next is the provision of taqwa, which is provision to the abode of settlement …"},{"bk":"saadi","s":3,"ay":115,"x":"ثم بين تعالى أن كل ما فعلوه من خير قليل أو كثير فإن الله تعالى سيقبله حيث كان صادراً عن إيمان وإخلاص، {فلن يكفروه}؛ يعني لن ينكر ما عملوه ولن يهدر {والله عليم بالمتقين}؛ وهم الذين قاموا بالخيرات وتركوا المحرمات لقصد رضا الله وطلب ثوابه.","w":"السعدي","en":"Then He made clear that whatever good they did, little or much, Allah will accept it, since it came from faith and sincerity: \"they will not be denied it\", meaning He will not disown what they did nor let it be wasted; \"and Allah is Knowing of the God-fearing\", who are those who carried out good deeds and abandoned the forbidden, seeking Allah's pleasure and His reward."}],"h":["sulama"]},{"id":"istabiqu","ch":"musaraa","t":"«فاستبقوا الخيرات»","e":"الأمر بالاستباق إلى الخيرات وما يؤخذ منه من المبادرة إلى الفضائل.","ay":[[2,148,148],[5,48,48]],"q":[{"bk":"saadi","s":5,"ay":48,"x":"ولهذا قال:{فاستبقوا الخيرات}؛ أي: بادروا إليها وأكملوها؛ فإنَّ الخيرات الشاملة لكلِّ فرضٍ ومستحبٍّ من حقوق الله وحقوق عبادِهِ لا يصير فاعلها سابقاً لغيره مستولياً على الأمر إلا بأمرين: المبادرة إليها، وانتهاز الفرصة حين يجيء وقتها ويعرِضُ عارضها، والاجتهاد في أدائها كاملة على الوجه المأمور به. ويستدلُّ بهذه الآية على المبادرة لأداء الصلاة وغيرها في أول وقتها، وعلى أنه ينبغي أن لا يقتصر العبد على مجرد ما يجزي في الصلاة وغيرها من العبادات من الأمور الواجبة، بل ينبغي أن يأتي بالمستحبَّات التي يقدر عليها لتتمَّ وتكْمُل ويحصل بها السبق.","w":"السعدي","en":"Hence He said: \"so race to good deeds\", that is, hasten to them and complete them. For the good deeds, which include every obligation and recommended act of the rights of Allah and the rights of His servants, do not make their doer ahead of others, in command of the matter, except through two things: hastening to them and seizing the opportunity when their time comes and their occasion arises, and striving to perform them fully in the way commanded. This verse is taken as evidence for hastening to perform prayer and other acts at the start of their time, and that a servant should not confine himself to the bare minimum that suffices in prayer and other acts of worship of obligatory matters, but should bring the recommended acts he is able to, so that it is completed and perfected and he attains the lead."},{"bk":"saadi","s":2,"ay":148,"x":"ويستدل بهذه الآية الشريفة على الإتيان بكل فضيلة يتصف بها العمل، كالصلاة في أول وقتها، والمبادرة إلى إبراء الذمة من الصيام والحجِّ والعمرة وإخراج الزكاة، والإتيان بسنن العبادات وآدابها، فلله ما أجمعها وأنفعها من آية.","w":"السعدي","en":"And this noble verse is taken as evidence for bringing every virtue with which a deed can be described, such as praying at the start of its time, hastening to discharge one's obligation of fasting, Hajj, Umra and paying zakat, and bringing the sunan and manners of acts of worship. How comprehensive and beneficial a verse it is!"}],"h":["badiru"]},{"id":"sariu","ch":"musaraa","t":"«وسارعوا إلى مغفرة من ربكم» و«سابقوا إلى مغفرة»","e":"الأمر بالمسارعة والمسابقة إلى مغفرة الله وجنته.","ay":[[3,133,133],[57,21,21]],"q":[{"bk":"saadi","s":3,"ay":133,"x":"ثم أمرهم تعالى بالمسارعة إلى مغفرته وإدراك جنته التي عرضها السماوات والأرض، فكيف بطولها التي أعدها الله للمتقين؟! فهم أهلها وأعمال التقوى هي الموصلة إليها.","w":"السعدي","en":"Then He commanded them to hasten to His forgiveness and to attain His Paradise, whose breadth is the heavens and the earth — so what of its length — which He prepared for the God-fearing. So they are its people, and deeds of taqwa are what lead to it."},{"bk":"saadi","s":57,"ay":21,"x":"ثم أمر بالمسابقة إلى مغفرة الله ورضوانه وجنته، وذلك يكون بالسعي بأسباب المغفرةِ من التوبة النَّصوح، والاستغفار النَّافع، والبعد عن الذُّنوب ومظانِّها، والمسابقة إلى رضوان الله بالعمل الصالح، والحرص على ما يُرضي الله على الدَّوام من الإحسان في عبادة الخالق، والإحسان إلى الخلق بجميع وجوه النفع، ولهذا ذكر الله الأعمالَ الموجبةَ لذلك، فقال:{وجنَّةٍ عرضُها السمواتُ والأرضُ أعِدَّتۡ للذين آمنوا باللهِ ورسلِهِ}، والإيمانُ بالله ورُسُلِهِ يدخلُ فيه أصولُ الدِّين وفروعها.","w":"السعدي","en":"Then He commanded racing to the forgiveness of Allah, His pleasure and His Paradise, and that is by striving after the causes of forgiveness: sincere repentance, beneficial seeking of forgiveness, keeping away from sins and what leads to them; and racing to Allah's pleasure through righteous deeds, and being keen on what pleases Allah constantly, from excellence in worship of the Creator and kindness to creatures in every kind of benefit. Hence Allah mentioned the deeds that bring that about, saying: \"and a Garden whose breadth is like the breadth of the heavens and earth, prepared for those who believe in Allah and His messengers\", and faith in Allah and His messengers includes the foundations of the religion and its branches."}],"h":[]},{"id":"anbiya","ch":"musaraa","t":"«إنهم كانوا يسارعون في الخيرات»: الأنبياء والمؤمنون","e":"وصف الأنبياء والمؤمنين المشفقين بأنهم يسارعون في الخيرات وهم لها سابقون.","ay":[[21,90,90],[23,57,61]],"q":[{"bk":"saadi","s":21,"ay":90,"x":"ولما ذَكَرَ هؤلاء الأنبياء والمرسلين كلًّا على انفراده؛ أثنى عليهم عموماً، فقال:{إنَّهم كانوا يسارِعون في الخيراتِ}؛ أي: يبادرون إليها، ويفعلونها في أوقاتها الفاضلة، ويكمِّلونها على الوجه اللائق الذي ينبغي، ولا يتركون فضيلةً يقدِرون عليها إلا انتهزوا الفرصة فيها.","w":"السعدي","en":"Then, having mentioned these prophets and messengers one by one, He praised them all together, saying: \"Indeed, they used to hasten to good deeds\", that is, they hurry to them, do them in their excellent times, complete them in the fitting way as they should be, and leave no virtue within their ability without seizing the opportunity in it."},{"bk":"ibnkathir","s":23,"ay":61,"x":"وَالْمَعْنَى عَلَى الْقِرَاءَةِ الْأُولَى -وَهِيَ قِرَاءَةُ الْجُمْهُورِ: السَّبْعَةِ وَغَيْرِهِمْ-أَظْهَرُ؛ لِأَنَّهُ قَالَ: ﴿أُولَئِكَ يُسَارِعُونَ فِي الْخَيْرَاتِ وَهُمْ لَهَا سَابِقُونَ﴾ ، فَجَعَلَهُمْ مِنَ السَّابِقِينَ.","w":"ابن كثير","en":"And the meaning according to the first reading, which is the reading of the majority, the seven and others, is the clearer, because He said: \"Those hasten to good deeds, and they outstrip others in them\", so He counted them among those who are foremost."}],"h":[]},{"id":"sabiq","ch":"musaraa","t":"«ومنهم سابق بالخيرات» و«والسابقون السابقون»","e":"ذكر السابق بالخيرات من الأصناف الثلاثة، والسابقين المقرّبين.","ay":[[35,32,32],[56,10,12]],"q":[{"bk":"saadi","s":35,"ay":32,"x":"{ومنهم مقتصدٌ}: مقتصرٌ على ما يجب عليه، تاركٌ للمحرَّم، {ومنهم سابقٌ بالخيرات}؛ أي: سَارَعَ فيها، واجْتَهَدَ فسبق غيره، وهو المؤدي للفرائض، المكثر من النوافل، التارك للمحرم والمكروه؛ فكلهم اصطفاه الله تعالى لوراثة هذا الكتاب، وإن تفاوتتْ مراتِبُهم وتميَّزت أحوالُهم؛ فلكل منهم قسطٌ من وراثتِهِ، حتى الظالم لنفسه؛ فإنَّ ما معه من أصل الإيمان وعلوم الإيمان وأعمال الإيمان من وراثة الكتاب؛ لأنَّ المراد بوراثة الكتاب وراثةُ علمِهِ وعمله ودراسةُ ألفاظِهِ واستخراج معانيه، وقوله:{بإذن الله}: راجعٌ إلى السابق إلى الخيرات ؛ لئلاَّ يغترَّ بعمله، بل ما سَبَقَ إلى الخيرات إلاَّ بتوفيق الله تعالى ومعونته؛ فينبغي له أن يشتغلَ بشكر الله تعالى على ما أنعم به عليه.","w":"السعدي","en":"\"And among them is one who is moderate\", content with what is obligatory on him and leaving what is forbidden, \"and among them is one foremost in good deeds\", that is, he hastened in them and strove, and so outstripped others; he performs the obligations, does many voluntary acts, and leaves the forbidden and the disliked. All of them Allah chose to inherit this Book, though their ranks differ and their states are distinct; each of them has a share of inheriting it, even the one who wrongs himself, for what he has of the root of faith, the knowledge of faith and the deeds of faith is of inheriting the Book; since what is meant by inheriting the Book is inheriting its knowledge and practice, studying its words and drawing out its meanings. And His words \"by permission of Allah\" refer to the one foremost in good deeds, lest he be deceived by his deed; he did not outstrip others in good deeds except by Allah's success and help, so he should busy himself thanking Allah for what He has bestowed on him."},{"bk":"saadi","s":56,"ay":10,"x":"{أولئك المقرَّبون}؛ أي: السابقون في الدنيا إلى الخيرات هم السابقون في الآخرة لدخول الجنات، أولئك الذين هذا وصفهم المقرَّبون عند الله {في جنات النعيم}: في أعلى علِّيين، في المنازل العاليات التي لا منزلة فوقها، وهؤلاء المذكورون {ثُلَّةٌ من الأوَّلين}؛ أي: جماعة كثيرون من المتقدِّمين من هذه الأمة وغيرهم.","w":"السعدي","en":"\"Those are the ones brought near\", that is, those foremost in this world to good deeds are the foremost in the Hereafter in entering the Gardens; those who are so described are the ones brought near to Allah \"in the Gardens of Pleasure\", in the highest of the elevated places, in the lofty stations above which there is no station. These mentioned are \"a multitude from the former peoples\", that is, a large group of the earlier ones of this community and others."}],"h":[]},{"id":"latawun","ch":"tawun","t":"«ولا تعاونوا على الإثم والعدوان»","e":"النهي عن التعاون على الإثم والعدوان، وبيان معنى الإثم والعدوان. وجانب الأمر بالتعاون على البر والتقوى في باب البر.","ay":[[5,2,2]],"q":[{"bk":"ibnkathir","s":5,"ay":2,"x":"قَالَ ابْنُ جَرِيرٍ: الْإِثْمُ: تَرْكُ مَا أَمَرَ اللَّهُ بِفِعْلِهِ، وَالْعُدْوَانُ: مُجَاوَزَةُ مَا حَدَّ اللَّهُ فِي دِينِكُمْ، وَمُجَاوَزَةُ مَا فَرَضَ عَلَيْكُمْ فِي أَنْفُسِكُمْ وَفِي غَيْرِكُمْ .","w":"ابن كثير","en":"Ibn Jarir said: Sin is leaving what Allah commanded to be done, and aggression is transgressing the limit Allah set in your religion and transgressing what He made obligatory upon you with regard to yourselves and others …"}],"h":[]},{"id":"ukhuwwa","ch":"tawun","t":"«إنما المؤمنون إخوة»","e":"عقد الأخوة بين المؤمنين وما يقتضيه من محبة بعضهم لبعض.","ay":[[49,10,10]],"q":[{"bk":"saadi","s":49,"ay":10,"x":"{إنَّما المؤمنونَ إخوةٌ}: هذا عقدٌ عقدَه الله بين المؤمنين؛ أنَّه إذا وجد من أيِّ شخصٍ كان في مشرق الأرض ومغربها الإيمانُ بالله وملائكته وكتبه ورسله واليوم الآخر؛ فإنَّه أخٌ للمؤمنين أخوَّةً توجبُ أن يحبَّ له المؤمنون ما يحبُّون لأنفسهم، ويكرهوا له ما يكرهون لأنفسهم …","w":"السعدي","en":"\"The believers are but brothers\": this is a bond that Allah made between the believers: whenever there is found in any person, in the east of the earth or its west, faith in Allah, His angels, His books, His messengers and the Last Day, he is a brother to the believers, in a brotherhood that requires the believers to love for him what they love for themselves and to dislike for him what they dislike for themselves …"},{"bk":"ibnkathir","s":49,"ay":10,"x":"وَقَوْلُهُ: ﴿إِنَّمَا الْمُؤْمِنُونَ إِخْوَةٌ﴾ أَيِ: الْجَمِيعُ إِخْوَةٌ فِي الدِّينِ …","w":"ابن كثير","en":"And His words: \"The believers are but brothers\", that is, all are brothers in religion …"}],"h":["tawadd"]},{"id":"bunyan","ch":"tawun","t":"«كأنهم بنيان مرصوص»","e":"وصف المقاتلين في سبيل الله صفاً كأنهم بنيان مرصوص.","ay":[[61,4,4]],"q":[{"bk":"saadi","s":61,"ay":4,"x":"هذا حثٌّ من الله لعباده على الجهاد في سبيله، وتعليمٌ لهم كيف يصنعون، وأنهم ينبغي لهم أن يَصُفُّوا في الجهاد صفًّا متراصًّا متساوياً من غير خلل يحصُلُ في الصفوف، وتكون صفوفُهم على نظام وترتيبٍ به تحصُلُ المساواة بين المجاهدين والتعاضُد وإرهاب العدوِّ وتنشيط بعضهم بعضاً، ولهذا كان النبيُّ - صلى الله عليه وسلم - إذا حضر القتال؛ صفّ أصحابه ورتَّبهم في مواقفهم بحيث لايحصُلُ اتِّكالُ بعضهم على بعض، بل تكون كلُّ طائفةٍ منهم مهتمةً بمركزها وقائمةً بوظيفتها، وبهذه الطريقة تتمُّ الأعمال ويحصُلُ الكمال.","w":"السعدي","en":"This is an urging from Allah to His servants to strive in His way, and a teaching to them of how to go about it: that they should form a ranked line in the fighting, firmly compacted and even, with no gap arising in the ranks, their ranks being in an order and arrangement by which equality, mutual support, the awe of the enemy and mutual encouragement are achieved. Hence the Prophet ﷺ, when he attended battle, would array his companions and arrange them in their positions so that none would rely on another, but each group would be attentive to its post and perform its task; and by this way deeds are completed and perfection is attained."}],"h":["bunyan"]},{"id":"ictisam","ch":"tawun","t":"«واعتصموا بحبل الله جميعاً ولا تفرقوا»","e":"الأمر بالاعتصام بحبل الله وعدم التفرق وتذكير الأمة بنعمة الائتلاف.","ay":[[3,103,103]],"q":[{"bk":"saadi","s":3,"ay":103,"x":"وذكرهم ما هم عليه قبل هذه النعمة وهو أنهم كانوا أعداء متفرقين فجمعهم بهذا الدين وألّف بين قلوبهم وجعلهم إخواناً، وكانوا على شفا حفرة من النار فأنقذهم من الشقاء، ونهج بهم طريق السعادة؛ لذلك بين {الله لكم آياته لعلكم تهتدون}؛ إلى شكر الله والتمسك بحبله.","w":"السعدي","en":"And He reminded them of what they were upon before this blessing: they were scattered enemies, and He united them through this religion, joined their hearts and made them brothers, when they were on the brink of a pit of Fire and He rescued them from wretchedness and set them on the path of happiness; hence He explained: \"Thus does Allah make clear to you His verses that you may be guided\" — to thank Allah and to hold to His rope."}],"h":[]},{"id":"tawasi","ch":"tawun","t":"«وتواصوا بالحق وتواصوا بالصبر» و«وتواصوا بالمرحمة»","e":"وصف الذين آمنوا بالتواصي بالحق والصبر والمرحمة.","ay":[[103,3,3],[90,17,17]],"q":[{"bk":"saadi","s":103,"ay":3,"x":"والتَّواصي بالحقِّ الذي هو الإيمان والعمل الصالح؛ أي: يوصي بعضُهم بعضاً بذلك، ويحثُّه عليه، ويرغِّبه فيه. والتَّواصي بالصَّبر على طاعة الله، وعن معصية الله، وعلى أقدار الله المؤلمة. فبالأمرين الأولين يكمِّل العبد نفسه، وبالأمرين الأخيرين يكمِّل غيره، وبتكميل الأمور الأربعة يكون العبد قد سلم من الخسار وفاز بالرِّبح العظيم.","w":"السعدي","en":"And counselling one another to the truth, which is faith and righteous deeds, that is, each urges the other to it, spurs him to it and makes him desire it. And counselling one another to patience in obeying Allah, in refraining from disobeying Allah, and in Allah's painful decrees. By the first two a servant perfects himself, and by the last two he perfects others; and by perfecting the four matters the servant is safe from loss and wins the great gain."},{"bk":"ibnkathir","s":90,"ay":17,"x":"وَقَوْلُهُ: ﴿وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ﴾ أَيْ: كَانَ مِنَ الْمُؤْمِنِينَ الْعَامِلِينَ صَالِحًا، الْمُتَوَاصِينَ بِالصَّبْرِ عَلَى أَذَى النَّاسِ، وَعَلَى الرَّحْمَةِ بِهِمْ.","w":"ابن كثير","en":"And His words: \"and counsel one another to patience and counsel one another to compassion\", that is, he was one of the believers who do righteous deeds, who counsel one another to patience in the face of people's harm and to mercy toward them."}],"h":[]},{"id":"azr","ch":"tawun","t":"الإعانة في الخير: «فأعينوني بقوة» و«سنشد عضدك بأخيك»","e":"طلب العون في الخير: ذو القرنين وقومه، وموسى وأخوه هارون.","ay":[[18,95,95],[20,29,32],[28,35,35]],"q":[{"bk":"saadi","s":18,"ay":95,"x":"فلم يكن ذو القرنين ذا طمع ولا رغبةٍ في الدُّنيا ولا تاركاً لإصلاح أحوال الرعيَّة، بل قصدُهُ الإصلاح؛ فلذلك أجاب طلبتهم؛ لما فيها من المصلحة، ولم يأخذ منهم أجرةً، وشَكَرَ ربَّه على تمكينه واقتداره، فقال لهم:{ما مَكَّنِّي فيه ربِّي خيرٌ}؛ أي: مما تبذلون لي وتعطوني، وإنَّما أطلب منكم أن تعينوني بقوَّةٍ منكم بأيديكم؛ {أجۡعَلۡ بينَكم وبينهم رَدۡماً}؛ أي: مانعاً من عبورهم عليكم.","w":"السعدي","en":"Dhu al-Qarnayn was not one with greed or desire for the world, nor one who neglects setting right the affairs of the subjects; rather his aim was reform, so he answered their request for the benefit in it and took no payment from them. He thanked his Lord for the authority and power He gave him and said to them: \"What my Lord has established me in is better\", that is, than what you offer me and give me; I only ask that you help me with strength from your hands: \"I will make between you and them a barrier\", that is, something that blocks their passage to you."},{"bk":"ibnkathir","s":28,"ay":35,"x":"فَلَمَّا سَأَلَ ذَلِكَ قَالَ اللَّهُ تَعَالَى: ﴿سَنَشُدُّ عَضُدَكَ بِأَخِيكَ﴾ أَيْ: سَنُقَوِّي أَمْرَكَ، وَنُعِزُّ جَانِبَكَ بِأَخِيكَ، الَّذِي سَأَلْتَ لَهُ أَنْ يَكُونَ نَبِيًّا مَعَكَ.","w":"ابن كثير","en":"When he asked that, Allah said: \"We will strengthen your arm through your brother\", that is, We will strengthen your cause and make your side mighty by your brother, whom you asked to be a prophet with you."},{"bk":"ibnkathir","s":20,"ay":29,"x":"وَقَوْلُهُ: ﴿وَاجْعَلْ لِي وَزِيرًا مِنْ أَهْلِي هَارُونَ أَخِي﴾ : وَهَذَا أَيْضًا سُؤَالٌ مِنْ مُوسَى فِي أَمْرٍ خَارِجِيٍّ عَنْهُ، وَهُوَ مُسَاعَدَةُ أَخِيهِ هَارُونَ لَهُ.","w":"ابن كثير","en":"And His words: \"And appoint for me a minister from my family, Harun, my brother\": and this too was a request by Musa in a matter outside himself, namely the assistance of his brother Harun to him."}],"h":["haja"]},{"id":"umma","ch":"umma","t":"«ولتكن منكم أمة يدعون إلى الخير»","e":"الأمر بأن تكون من الجماعة أمة تدعو إلى الخير وتأمر بالمعروف وتنهى عن المنكر.","ay":[[3,104,104]],"q":[{"bk":"saadi","s":3,"ay":104,"x":"وأمرهم بتتميم هذه الحالة، والسبب الأقوى الذي يتمكنون به من إقامة دينهم بأن يتصدى منهم طائفة يحصل فيها الكفاية {يدعون إلى الخير}؛ وهو الدين: أصوله وفروعه وشرائعه {ويأمرون بالمعروف}؛ وهو ما عرف حسنه شرعاً وعقلاً {وينهون عن المنكر}؛ وهو ما عرف قبحه شرعاً وعقلاً {وأولئك هم المفلحون}؛ المدركون لكل مطلوب الناجون من كل مرهوب، ويدخل في هذه الطائفة أهل العلم والتعليم والمتصدون للخطابة ووعظ الناس عموماً وخصوصاً والمحتسبون، الذين يقومون بإلزام الناس بإقامة الصلوات وإيتاء الزكاة والقيام بشرائع الدين، وينهونهم عن المنكرات. فكل من دعا الناس إلى خير على وجه العموم أو على وجه الخصوص، أو قام بنصيحة عامة أو خاصة فإنه داخل في هذه الآية الكريمة.","w":"السعدي","en":"And He commanded them to complete this state, the strongest means by which they can establish their religion: that a group from among them take it upon themselves, enough to suffice, \"calling to good\", which is the religion, its foundations, branches and laws; \"enjoining what is right\", which is what is known to be good by the Sharia and reason; \"and forbidding what is wrong\", which is what is known to be bad by the Sharia and reason; \"and those are the successful\", those who attain every desired thing and are saved from every feared thing. In this group are the people of knowledge and teaching, those who take on preaching and exhorting people in general and in particular, and the muhtasibs who see that people establish the prayers, pay zakat and observe the laws of the religion and forbid them what is wrong. So whoever calls people to good, in general or in particular, or offers general or particular counsel, is included in this noble verse."},{"bk":"ibnkathir","s":3,"ay":104,"x":"وَالْمَقْصُودُ مِنْ هَذِهِ الْآيَةِ أَنْ تَكُونَ فرْقَة مِنَ الأمَّة مُتَصَدِّيَةٌ لِهَذَا الشَّأْنِ، وَإِنْ كَانَ ذَلِكَ وَاجِبًا عَلَى كُلِّ فَرْدٍ مِنَ الْأُمَّةِ بِحَسْبِهِ …","w":"ابن كثير","en":"And the aim of this verse is that a group of the community should be set up for this task, even though it is an obligation on every individual of the community according to his capacity …"}],"h":[]},{"id":"khayrumma","ch":"umma","t":"«كنتم خير أمة أخرجت للناس»","e":"وصف الأمة بأنها خير أمة أخرجت للناس بالأمر بالمعروف والنهي عن المنكر والإيمان.","ay":[[3,110,110]],"q":[{"bk":"saadi","s":3,"ay":110,"x":"هذا تفضيل من الله لهذه الأمة بهذه الأسباب، التي تميزوا بها وفاقوا بها سائر الأمم، وأنهم خير الناس للناس نصحاً ومحبة للخير ودعوة وتعليماً وإرشاداً وأمراً بالمعروف ونهياً عن المنكر وجمعاً بين تكميل الخلق والسعي في منافعهم بحسب الإمكان، وبين تكميل النفس بالإيمان بالله والقيام بحقوق الإيمان، وأن أهل الكتاب لو آمنوا بمثل ما آمنتم به لاهتدوا وكان خيراً لهم ولكن لم يؤمن منهم إلا القليل، وأما الكثير فهم فاسقون خارجون عن طاعة الله وطاعة رسوله محاربون للمؤمنين ساعون في إضرارهم بكل مقدورهم، ومع ذلك فلن يضروا المؤمنين إلا أذى باللسان، وإلا فلو قاتلوهم لولوا الأدبار ثم لا ينصرون.","w":"السعدي","en":"This is Allah's preferring of this community for these reasons by which they stood out and surpassed all other peoples: that they are the best of people for people in sincere counsel, love of good, calling, teaching and guidance, enjoining what is right and forbidding what is wrong, combining the perfecting of creation and striving for their benefit as far as possible with the perfecting of the self by faith in Allah and fulfilling the rights of faith. And that had the People of the Book believed as you have believed, they would have been guided and it would have been better for them, but only a few of them believed, while most are defiantly disobedient, departing from obedience to Allah and His Messenger, fighting the believers and striving to harm them with all their power; and yet they will not harm the believers except with a trifling annoyance of the tongue, and if they fought them they would turn their backs, then not be helped."}],"h":[]},{"id":"amr","ch":"umma","t":"«يأمرون بالمعروف وينهون عن المنكر» و«وأمر بالمعروف وانه عن المنكر»","e":"وصف المؤمنين والمؤمنات بالأمر بالمعروف والنهي عن المنكر، ووصية لقمان لابنه بذلك.","ay":[[9,71,71],[31,17,17]],"q":[{"bk":"saadi","s":9,"ay":71,"x":"وهو اسمٌ جامعٌ لكلِّ ما عُرِف حسنه من العقائد الحسنة والأعمال الصالحة والأخلاق الفاضلة، وأول مَن يدخُلُ في أمرهم أنفسُهم. {وينهَوۡن عن المنكر}: وهو كلُّ ما خالف المعروف، وناقَضَه من العقائد الباطلة والأعمال الخبيثة والأخلاق الرذيلة، {ويطيعونَ الله ورسوله}؛ أي: لا يزالون ملازمين لطاعة الله ورسوله على الدوام.","w":"السعدي","en":"It is a comprehensive name for everything whose goodness is known, of good beliefs, righteous deeds and noble character, and the first to be included in their commanding is themselves. \"And forbid what is wrong\": it is everything that contradicts the right and negates it, of false beliefs, vile deeds and base character; \"and obey Allah and His Messenger\", that is, they remain constantly bound to obeying Allah and His Messenger."},{"bk":"saadi","s":31,"ay":17,"x":"{يا بنيَّ أقِمِ الصَّلاة}: حثَّه عليها وخصَّها لأنَّها أكبرُ العبادات البدنيَّة، {وأمُرۡ بالمعروفِ وانۡهَ عن المنكرِ}: وذلك يستلزم العلم بالمعروف؛ ليأمر به، والعلم بالمنكر؛ لينهى عنه، والأمر بما لا يتمُّ الأمر بالمعروف، والنهي عن المنكر إلاَّ به، من الرفق والصبر، وقد صرَّح به في قوله:{واصۡبِرۡ على ما أصابك}: ومن كونه فاعلاً لما يأمر به، كافًّا لما يُنهى عنه، فتضمَّن هذا تكميلَ نفسه بفعل الخير وترك الشر، وتكميلَ غيره بذلك بأمره ونهيه.","w":"السعدي","en":"\"O my son, establish prayer\": he urged him to it and singled it out because it is the greatest of bodily acts of worship; \"and enjoin what is right and forbid what is wrong\": that requires knowledge of the right in order to enjoin it and knowledge of the wrong in order to forbid it, and the gentleness and patience without which enjoining and forbidding are not complete, as He made explicit in His words \"and be patient over what befalls you\"; and also that he himself does what he enjoins and refrains from what he forbids. So this includes perfecting oneself by doing good and leaving evil, and perfecting others by commanding and forbidding."}],"h":["ghayyir"]},{"id":"ahsan","ch":"umma","t":"«ومن أحسن قولاً ممن دعا إلى الله وعمل صالحاً»","e":"ثناء الله على من دعا إلى الله وعمل صالحاً، وبيان صور الدعوة.","ay":[[41,33,33]],"q":[{"bk":"saadi","s":41,"ay":33,"x":"ومن الدعوة إلى الله تحبيبُهُ إلى عبادِهِ؛ بذِكْر تفاصيل نِعَمِهِ وسعةِ جودِهِ وكمال رحمتِهِ وذكرِ أوصاف كمالِهِ ونعوت جلاله. ومن الدعوة إلى الله الترغيبُ في اقتباس العلم والهدى من كتاب الله وسنَّة رسوله، والحثُّ على ذلك بكلِّ طريق موصل إليه. ومن ذلك الحثُّ على مكارم الأخلاق، والإحسانُ إلى عموم الخلق، ومقابلةُ المسيء بالإحسان، والأمرُ بصلة الأرحام وبرِّ الوالدين.","w":"السعدي","en":"Part of calling to Allah is making Him beloved to His servants by mentioning the details of His blessings, the breadth of His generosity, the perfection of His mercy, and mentioning His attributes of perfection and His epithets of majesty. And part of calling to Allah is encouraging people to acquire knowledge and guidance from the Book of Allah and the Sunnah of His Messenger, and urging that by every way that leads to it. And part of that is urging noble character, kindness to all people, repaying the wrongdoer with kindness, and enjoining the keeping of kinship ties and dutifulness to parents."}],"h":["dalla","huda"]},{"id":"baqiyya","ch":"umma","t":"«أولو بقية ينهون عن الفساد في الأرض» و«أمة يهدون بالحق»","e":"بقية أهل الخير الذين ينهون عن الفساد، وأمة من الناس تهدي بالحق وبه تعدل.","ay":[[11,116,116],[7,181,181]],"q":[{"bk":"saadi","s":11,"ay":116,"x":"وفي هذا حثٌّ لهذه الأمة أن يكون فيهم بقايا؛ مصلحون لما أفسد الناس، قائمون بدين الله، يدعون من ضلَّ إلى الهدى، ويصبرون منهم على الأذى، ويبصِّرونهم من العمى، وهذه الحالة أعلى حالة يرغب فيها الراغبون، وصاحبها يكون إماماً في الدين؛ إذا جعل عمله خالصاً لربِّ العالمين.","w":"السعدي","en":"And in this is an urging to this community that there be among them remnants who set right what people have corrupted, uphold the religion of Allah, call the misguided to guidance, bear their harm patiently and give sight to the blind; and this is the highest state that those who aspire may seek, and its holder becomes an imam in religion if he makes his deed sincerely for the Lord of the worlds."},{"bk":"saadi","s":7,"ay":181,"x":"أي: ومن جملة من خلقنا أمة فاضلة كاملة في نفسها مكمِّلة لغيرها يهدون أنفسهم وغيرهم بالحقِّ فيعلمون الحقَّ ويعملون به ويعلِّمونه ويدعون إليه وإلى العمل به.","w":"السعدي","en":"That is: and among those We created is a community excellent in itself and perfecting of others, who guide themselves and others by the truth, so they know the truth, act by it, teach it and call to it and to acting by it."}],"h":[]},{"id":"tanahawn","ch":"umma","t":"«كانوا لا يتناهون عن منكر فعلوه»","e":"ذمّ من كانوا لا يتناهون عن منكر فعلوه.","ay":[[5,78,79]],"q":[{"bk":"saadi","s":5,"ay":79,"x":"وإنَّما كان السكوت عن المنكَرِ مع القدرة موجباً للعقوبة لما فيه من المفاسد العظيمة: منها: أنَّ مجرَّد السكوت فعلُ معصيةٍ، وإنْ لم يباشِرْها الساكتُ؛ فإنَّه كما يجب اجتناب المعصية؛ فإنَّه يجب الإنكار على مَنْ فَعَلَ المعصية. ومنها: ما تقدَّم أنه يدلُّ على التهاون بالمعاصي وقلة الاكتراث بها.","w":"السعدي","en":"Silence about wrongdoing despite being able to act deserves punishment because of the great harms in it: among them, that mere silence is itself an act of disobedience, even if the one silent did not commit it; for just as avoiding disobedience is obligatory, so is objecting to the one who commits it. And among them, as already mentioned, that it shows making light of acts of disobedience and little concern for them."},{"bk":"ibnkathir","s":5,"ay":79,"x":"ثُمَّ بَيَّنَ حَالَهُمْ فِيمَا كَانُوا يَعْتَمِدُونَهُ فِي زَمَانِهِمْ، فَقَالَ: ﴿كَانُوا لَا يَتَنَاهَوْنَ عَنْ مُنْكَرٍ فَعَلُوهُ لَبِئْسَ مَا كَانُوا يَفْعَلُونَ﴾ أَيْ: كَانَ لَا يَنْهَى أَحَدٌ مِنْهُمْ أَحَدًا عَنِ ارْتِكَابِ الْمَآثِمِ وَالْمَحَارِمِ، ثُمَّ ذَمَّهُمْ عَلَى ذَلِكَ لِيُحَذَرَ أَنْ يُرْكَبَ مِثْلُ الَّذِي ارْتَكَبُوا …","w":"ابن كثير","en":"Then He explained their state in what they relied on in their time, saying: \"They did not forbid one another any wrong they did; wretched indeed was what they were doing\", meaning that none of them forbade another from committing sins and prohibitions; then He censured them for that so that one would beware of committing what they committed …"}],"h":["safina"]},{"id":"imara","ch":"imara","t":"«إنما يعمر مساجد الله من آمن بالله واليوم الآخر»","e":"وصف عمّار مساجد الله بالإيمان وإقامة الصلاة وإيتاء الزكاة وخشية الله وحده.","ay":[[9,17,18]],"q":[{"bk":"saadi","s":9,"ay":18,"x":"ثم ذكر من هم عُمَّار مساجد الله، فقال:{إنَّما يَعۡمُرُ مساجدَ الله مَن آمن بالله واليوم الآخر وأقام الصلاة}: الواجبة والمستحبَّة بالقيام بالظَّاهر منها والباطن، {وآتى الزكاة}: لأهلها، {ولم يَخۡشَ إلا الله}؛ أي: قَصَرَ خشيته على ربِّه، فكفَّ عن ما حرَّم الله، ولم يقصِّر بحقوق الله الواجبة؛ فوصفهم بالإيمان النافع، وبالقيام بالأعمال الصالحة التي أُمُّها الصلاة والزكاة، وبخشية الله التي هي أصل كلِّ خير؛ فهؤلاء عُمَّار المساجد على الحقيقة وأهلُها الذين هم أهلها.","w":"السعدي","en":"Then He mentioned who the maintainers of Allah's mosques are, saying: \"Only one who believes in Allah and the Last Day and establishes prayer\" — obligatory and recommended, in its outward and inward aspects — \"and gives zakat\" to its people, \"and fears none but Allah\", that is, restricted his fear to his Lord, so he refrained from what Allah forbade and did not fall short in the obligatory rights of Allah. So He described them with beneficial faith, and with doing righteous deeds, of which the mother is prayer and zakat, and with fear of Allah, which is the root of every good; these are the true maintainers of mosques and its rightful people."},{"bk":"ibnkathir","s":9,"ay":18,"x":"وَقَوْلُهُ: ﴿وَأَقَامَ الصَّلاةَ﴾ أَيْ: الَّتِي هِيَ أَكْبَرُ عِبَادَاتِ الْبَدَنِ، ﴿وَآتَى الزَّكَاةَ﴾ أَيْ: الَّتِي هِيَ أَفْضَلُ الْأَعْمَالِ الْمُتَعَدِّيَةِ إِلَى بِرِّ الْخَلَائِقِ، ﴿وَلَمْ يَخْشَ إِلا اللَّهَ﴾ أَيْ: وَلَمْ يَخَفْ إِلَّا مِنَ اللَّهِ تَعَالَى، وَلَمْ يَخْشَ سِوَاهُ …","w":"ابن كثير","en":"And His words: \"and establishes prayer\", meaning that which is the greatest of the bodily acts of worship, \"and gives zakat\", meaning that which is the best of the deeds that extend to doing good to creatures, \"and fears none but Allah\", meaning he fears only Allah and fears no other besides Him …"}],"h":["masjid"]},{"id":"siqaya","ch":"imara","t":"«أجعلتم سقاية الحاج وعمارة المسجد الحرام»","e":"الموازنة بين سقاية الحاج وعمارة المسجد الحرام وبين الإيمان والجهاد.","ay":[[9,19,22]],"q":[{"bk":"saadi","s":9,"ay":19,"x":"لما اختلف بعضُ المسلمين أو بعضُ المسلمين وبعضُ المشركين في تفضيل عِمارة المسجد الحرام بالبناء والصلاة والعبادة فيه وسقاية الحاجِّ على الإيمان بالله والجهاد في سبيله؛ أخبر الله تعالى بالتفاوتِ بينهما، فقال:{أجعلتُم سِقايةَ الحاجِّ}؛ أي: سقيهم الماء من زمزم؛ كما هو المعروف إذا أطلق هذا الاسم أنه المراد، {وعِمارةَ المسجدِ الحرام كمن آمَنَ بالله واليوم الآخر وجاهَدَ في سبيل الله لا يستوون عند الله}: فالجهادُ والإيمان بالله أفضلُ من سقاية الحاجِّ وعمارة المسجد الحرام بدرجاتٍ كثيرةٍ؛ لأنَّ الإيمان أصلُ الدين وبه تُقبل الأعمال وتزكو الخصال، وأمَّا الجهاد في سبيل الله؛ فهو ذروة سنام الدين، [الذي] به يُحفظ الدين الإسلامي ويتَّسع، ويُنْصَر الحقُّ ويُخْذَل الباطل، وأمَّا عِمارة المسجد الحرام وسقاية الحاجِّ؛ فهي، وإن كانت أعمالاً صالحةً؛ فهي متوقِّفة على الإيمان …","w":"السعدي","en":"When some Muslims, or some Muslims and some polytheists, disagreed about the superiority of tending the Sacred Mosque by building, prayer and worship in it and giving water to pilgrims over faith in Allah and striving in His way, Allah the Exalted announced the difference between them, saying: \"Have you made the giving of water to pilgrims\", that is, giving them water from Zamzam, as is known when this name is used it is what is meant, \"and the tending of the Sacred Mosque equal to one who believes in Allah and the Last Day and strives in the way of Allah? They are not equal with Allah\". So striving and faith in Allah are better than giving water to pilgrims and tending the Sacred Mosque by many degrees; for faith is the root of the religion, by it deeds are accepted and traits purified; and as for striving in Allah's way, it is the summit of the religion, by which the religion of Islam is preserved and spreads, truth is supported and falsehood abandoned; and as for tending the Sacred Mosque and giving water to pilgrims, though they are righteous deeds, they depend on faith …"}],"h":[]},{"id":"makkanna","ch":"imara","t":"«الذين إن مكناهم في الأرض أقاموا الصلاة وآتوا الزكاة وأمروا بالمعروف»","e":"وصف من مكّنهم الله في الأرض بإقامة الصلاة وإيتاء الزكاة والأمر بالمعروف والنهي عن المنكر.","ay":[[22,41,41]],"q":[{"bk":"saadi","s":22,"ay":41,"x":"وهذا يشمَلُ كلِّ معروفٍ حُسْنُهُ شرعاً وعقلاً من حقوق الله وحقوق الآدميين. {ونَهَوا عن المنكر}: كلّ منكرٍ شرعاً وعقلاً، معروف قبحُه، والأمر بالشيء والنهي عنه يدخُلُ فيه ما لا يتمُّ إلاَّ به؛ فإذا كان المعروف والمنكر يتوقَّف على تعلُّم وتعليم أجبروا الناس على التعلُّم والتعليم، وإذا كان يتوقَّف على تأديبٍ مقدَّر شرعاً أو غير مقدَّر؛ كأنواع التعزير؛ قاموا بذلك، وإذا كان يتوقَّف على جعل أناس متصدِّين له؛ لزم ذلك، ونحو ذلك مما لا يتمُّ الأمر بالمعروف والنهيُ عن المنكر إلاَّ به …","w":"السعدي","en":"And this includes every right whose goodness is known by the Sharia and reason, of the rights of Allah and the rights of human beings. \"And forbid what is wrong\": every wrong known by the Sharia and reason to be ugly; and commanding a thing and forbidding it includes what cannot be done without it. So if the right and wrong depend on learning and teaching, they compel people to learn and teach; if it depends on a fixed or unfixed discipline in the Sharia, such as types of ta'zir, they carry that out; and if it depends on appointing people to take charge of it, that becomes necessary, and the like of what enjoining the right and forbidding the wrong cannot be complete without …"}],"h":[]}],"ay":{"154":"وَلِكُلّٖ وِجۡهَةٌ هُوَ مُوَلِّيهَاۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ أَيۡنَ مَا تَكُونُواْ يَأۡتِ بِكُمُ ٱللَّهُ جَمِيعًاۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","164":"۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ","190":"أَيَّامٗا مَّعۡدُودَٰتٖۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ عَلَىٰ سَفَرٖ فَعِدَّةٞ مِّنۡ أَيَّامٍ أُخَرَۚ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدۡيَةٞ طَعَامُ مِسۡكِينٖۖ فَمَن تَطَوَّعَ خَيۡرٗا فَهُوَ خَيۡرٞ لَّهُۥۚ وَأَن تَصُومُواْ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","203":"ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ","395":"وَٱعۡتَصِمُواْ بِحَبۡلِ ٱللَّهِ جَمِيعٗا وَلَا تَفَرَّقُواْۚ وَٱذۡكُرُواْ نِعۡمَتَ ٱللَّهِ عَلَيۡكُمۡ إِذۡ كُنتُمۡ أَعۡدَآءٗ فَأَلَّفَ بَيۡنَ قُلُوبِكُمۡ فَأَصۡبَحۡتُم بِنِعۡمَتِهِۦٓ إِخۡوَٰنٗا وَكُنتُمۡ عَلَىٰ شَفَا حُفۡرَةٖ مِّنَ ٱلنَّارِ فَأَنقَذَكُم مِّنۡهَاۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَهۡتَدُونَ","396":"وَلۡتَكُن مِّنكُمۡ أُمَّةٞ يَدۡعُونَ إِلَى ٱلۡخَيۡرِ وَيَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ","402":"كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ وَلَوۡ ءَامَنَ أَهۡلُ ٱلۡكِتَٰبِ لَكَانَ خَيۡرٗا لَّهُمۚ مِّنۡهُمُ ٱلۡمُؤۡمِنُونَ وَأَكۡثَرُهُمُ ٱلۡفَٰسِقُونَ","407":"وَمَا يَفۡعَلُواْ مِنۡ خَيۡرٖ فَلَن يُكۡفَرُوهُۗ وَٱللَّهُ عَلِيمُۢ بِٱلۡمُتَّقِينَ","425":"۞ وَسَارِعُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا ٱلسَّمَٰوَٰتُ وَٱلۡأَرۡضُ أُعِدَّتۡ لِلۡمُتَّقِينَ","670":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُحِلُّواْ شَعَٰٓئِرَ ٱللَّهِ وَلَا ٱلشَّهۡرَ ٱلۡحَرَامَ وَلَا ٱلۡهَدۡيَ وَلَا ٱلۡقَلَٰٓئِدَ وَلَآ ءَآمِّينَ ٱلۡبَيۡتَ ٱلۡحَرَامَ يَبۡتَغُونَ فَضۡلٗا مِّن رَّبِّهِمۡ وَرِضۡوَٰنٗاۚ وَإِذَا حَلَلۡتُمۡ فَٱصۡطَادُواْۚ وَلَا يَجۡرِمَنَّكُمۡ شَنَـَٔانُ قَوۡمٍ أَن صَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ أَن تَعۡتَدُواْۘ وَتَعَاوَنُواْ عَلَى ٱلۡبِرِّ وَٱلتَّقۡوَىٰۖ وَلَا تَعَاوَنُواْ عَلَى ٱلۡإِثۡمِ وَٱلۡعُدۡوَٰنِۚ وَٱتَّقُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ","716":"وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","746":"لُعِنَ ٱلَّذِينَ كَفَرُواْ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ عَلَىٰ لِسَانِ دَاوُۥدَ وَعِيسَى ٱبۡنِ مَرۡيَمَۚ ذَٰلِكَ بِمَا عَصَواْ وَّكَانُواْ يَعۡتَدُونَ","747":"كَانُواْ لَا يَتَنَاهَوۡنَ عَن مُّنكَرٖ فَعَلُوهُۚ لَبِئۡسَ مَا كَانُواْ يَفۡعَلُونَ","1134":"وَمِمَّنۡ خَلَقۡنَآ أُمَّةٞ يَهۡدُونَ بِٱلۡحَقِّ وَبِهِۦ يَعۡدِلُونَ","1251":"مَا كَانَ لِلۡمُشۡرِكِينَ أَن يَعۡمُرُواْ مَسَٰجِدَ ٱللَّهِ شَٰهِدِينَ عَلَىٰٓ أَنفُسِهِم بِٱلۡكُفۡرِۚ أُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ وَفِي ٱلنَّارِ هُمۡ خَٰلِدُونَ","1252":"إِنَّمَا يَعۡمُرُ مَسَٰجِدَ ٱللَّهِ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَلَمۡ يَخۡشَ إِلَّا ٱللَّهَۖ فَعَسَىٰٓ أُوْلَٰٓئِكَ أَن يَكُونُواْ مِنَ ٱلۡمُهۡتَدِينَ","1253":"۞ أَجَعَلۡتُمۡ سِقَايَةَ ٱلۡحَآجِّ وَعِمَارَةَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ كَمَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَجَٰهَدَ فِي سَبِيلِ ٱللَّهِۚ لَا يَسۡتَوُۥنَ عِندَ ٱللَّهِۗ وَٱللَّهُ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ","1254":"ٱلَّذِينَ ءَامَنُواْ وَهَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ أَعۡظَمُ دَرَجَةً عِندَ ٱللَّهِۚ وَأُوْلَٰٓئِكَ هُمُ ٱلۡفَآئِزُونَ","1255":"يُبَشِّرُهُمۡ رَبُّهُم بِرَحۡمَةٖ مِّنۡهُ وَرِضۡوَٰنٖ وَجَنَّٰتٖ لَّهُمۡ فِيهَا نَعِيمٞ مُّقِيمٌ","1256":"خَٰلِدِينَ فِيهَآ أَبَدًاۚ إِنَّ ٱللَّهَ عِندَهُۥٓ أَجۡرٌ عَظِيمٞ","1305":"وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ يَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَيَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤۡتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓۚ أُوْلَٰٓئِكَ سَيَرۡحَمُهُمُ ٱللَّهُۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","1313":"ٱلَّذِينَ يَلۡمِزُونَ ٱلۡمُطَّوِّعِينَ مِنَ ٱلۡمُؤۡمِنِينَ فِي ٱلصَّدَقَٰتِ وَٱلَّذِينَ لَا يَجِدُونَ إِلَّا جُهۡدَهُمۡ فَيَسۡخَرُونَ مِنۡهُمۡ سَخِرَ ٱللَّهُ مِنۡهُمۡ وَلَهُمۡ عَذَابٌ أَلِيمٌ","1588":"فَلَوۡلَا كَانَ مِنَ ٱلۡقُرُونِ مِن قَبۡلِكُمۡ أُوْلُواْ بَقِيَّةٖ يَنۡهَوۡنَ عَنِ ٱلۡفَسَادِ فِي ٱلۡأَرۡضِ إِلَّا قَلِيلٗا مِّمَّنۡ أَنجَيۡنَا مِنۡهُمۡۗ وَٱتَّبَعَ ٱلَّذِينَ ظَلَمُواْ مَآ أُتۡرِفُواْ فِيهِ وَكَانُواْ مُجۡرِمِينَ","2234":"قَالَ مَا مَكَّنِّي فِيهِ رَبِّي خَيۡرٞ فَأَعِينُونِي بِقُوَّةٍ أَجۡعَلۡ بَيۡنَكُمۡ وَبَيۡنَهُمۡ رَدۡمًا","2376":"وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي","2377":"هَٰرُونَ أَخِي","2378":"ٱشۡدُدۡ بِهِۦٓ أَزۡرِي","2379":"وَأَشۡرِكۡهُ فِيٓ أَمۡرِي","2572":"فَٱسۡتَجَبۡنَا لَهُۥ وَوَهَبۡنَا لَهُۥ يَحۡيَىٰ وَأَصۡلَحۡنَا لَهُۥ زَوۡجَهُۥٓۚ إِنَّهُمۡ كَانُواْ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَيَدۡعُونَنَا رَغَبٗا وَرَهَبٗاۖ وَكَانُواْ لَنَا خَٰشِعِينَ","2635":"ٱلَّذِينَ إِن مَّكَّنَّٰهُمۡ فِي ٱلۡأَرۡضِ أَقَامُواْ ٱلصَّلَوٰةَ وَءَاتَوُاْ ٱلزَّكَوٰةَ وَأَمَرُواْ بِٱلۡمَعۡرُوفِ وَنَهَوۡاْ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَٰقِبَةُ ٱلۡأُمُورِ","2729":"إِنَّ ٱلَّذِينَ هُم مِّنۡ خَشۡيَةِ رَبِّهِم مُّشۡفِقُونَ","2730":"وَٱلَّذِينَ هُم بِـَٔايَٰتِ رَبِّهِمۡ يُؤۡمِنُونَ","2731":"وَٱلَّذِينَ هُم بِرَبِّهِمۡ لَا يُشۡرِكُونَ","2732":"وَٱلَّذِينَ يُؤۡتُونَ مَآ ءَاتَواْ وَّقُلُوبُهُمۡ وَجِلَةٌ أَنَّهُمۡ إِلَىٰ رَبِّهِمۡ رَٰجِعُونَ","2733":"أُوْلَٰٓئِكَ يُسَٰرِعُونَ فِي ٱلۡخَيۡرَٰتِ وَهُمۡ لَهَا سَٰبِقُونَ","3286":"قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجۡعَلُ لَكُمَا سُلۡطَٰنٗا فَلَا يَصِلُونَ إِلَيۡكُمَا بِـَٔايَٰتِنَآۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَٰلِبُونَ","3485":"يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","3691":"ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَٰبَ ٱلَّذِينَ ٱصۡطَفَيۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمٞ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدٞ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَيۡرَٰتِ بِإِذۡنِ ٱللَّهِۚ ذَٰلِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِيرُ","4250":"وَمَنۡ أَحۡسَنُ قَوۡلٗا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَٰلِحٗا وَقَالَ إِنَّنِي مِنَ ٱلۡمُسۡلِمِينَ","4621":"إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ","4988":"وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ","4989":"أُوْلَٰٓئِكَ ٱلۡمُقَرَّبُونَ","4990":"فِي جَنَّٰتِ ٱلنَّعِيمِ","5095":"سَابِقُوٓاْ إِلَىٰ مَغۡفِرَةٖ مِّن رَّبِّكُمۡ وَجَنَّةٍ عَرۡضُهَا كَعَرۡضِ ٱلسَّمَآءِ وَٱلۡأَرۡضِ أُعِدَّتۡ لِلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦۚ ذَٰلِكَ فَضۡلُ ٱللَّهِ يُؤۡتِيهِ مَن يَشَآءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِيمِ","5166":"إِنَّ ٱللَّهَ يُحِبُّ ٱلَّذِينَ يُقَٰتِلُونَ فِي سَبِيلِهِۦ صَفّٗا كَأَنَّهُم بُنۡيَٰنٞ مَّرۡصُوصٞ","6039":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","6178":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ"},"h":{"tatawwuh":{"id":"tatawwuh","t":"«إلا أن تطوّع شيئاً»","x":"أَخْبِرْنِي مَاذَا فَرَضَ اللَّهُ عَلَىَّ مِنَ الصَّلاَةِ فَقَالَ \" الصَّلَوَاتِ الْخَمْسَ، إِلاَّ أَنْ تَطَّوَّعَ شَيْئًا \". فَقَالَ أَخْبِرْنِي مَا فَرَضَ اللَّهُ عَلَىَّ مِنَ الصِّيَامِ فَقَالَ \" شَهْرَ رَمَضَانَ، إِلاَّ أَنْ تَطَّوَّعَ شَيْئًا \". فَقَالَ أَخْبِرْنِي بِمَا فَرَضَ اللَّهُ عَلَىَّ مِنَ الزَّكَاةِ فَقَالَ فَأَخْبَرَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم شَرَائِعَ الإِسْلاَمِ. قَالَ وَالَّذِي أَكْرَمَكَ لاَ أَتَطَوَّعُ شَيْئًا، وَلاَ أَنْقُصُ مِمَّا فَرَضَ اللَّهُ عَلَىَّ شَيْئًا. فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" أَفْلَحَ إِنْ صَدَقَ، أَوْ دَخَلَ الْجَنَّةَ إِنْ صَدَقَ","b":"bukhari","k":"1891","gr":"صحيح","en":"A Bedouin with dishevelled hair came to the Messenger of Allah ﷺ and said: \"O Messenger of Allah, tell me what Allah has made obligatory for me of prayer.\" He said: \"The five prayers, unless you volunteer something.\" He said: \"Tell me what Allah has made obligatory for me of fasting.\" He said: \"The month of Ramadan, unless you volunteer something.\" Then he said: \"Tell me what Allah has made obligatory for me of zakat,\" and the Messenger of Allah ﷺ informed him of the laws of Islam. He said: \"By the One who honoured you, I will not volunteer anything, nor will I reduce anything of what Allah has made obligatory on me.\" The Messenger of Allah ﷺ said: \"He has succeeded if he is truthful,\" or \"He will enter Paradise if he is truthful.\""},"sulama":{"id":"sulama","t":"كل سلامى من الناس عليه صدقة","x":"كُلُّ سُلاَمَى مِنَ النَّاسِ عَلَيْهِ صَدَقَةٌ كُلَّ يَوْمٍ تَطْلُعُ فِيهِ الشَّمْسُ، يَعْدِلُ بَيْنَ الاِثْنَيْنِ صَدَقَةٌ، وَيُعِينُ الرَّجُلَ عَلَى دَابَّتِهِ، فَيَحْمِلُ عَلَيْهَا، أَوْ يَرْفَعُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ، وَالْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ، وَكُلُّ خَطْوَةٍ يَخْطُوهَا إِلَى الصَّلاَةِ صَدَقَةٌ، وَيُمِيطُ الأَذَى عَنِ الطَّرِيقِ صَدَقَةٌ","b":"bukhari","k":"2989","gr":"صحيح","en":"\"Every joint of a person owes charity every day the sun rises: to judge justly between two people is charity; to help a man with his mount, lifting him onto it or raising his baggage onto it, is charity; a good word is charity; every step taken toward the prayer is charity; and removing harm from the road is charity.\""},"badiru":{"id":"badiru","t":"المبادرة بالأعمال قبل الفتن","x":"بَادِرُوا بِالأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا وَيُمْسِي كَافِرًا أَوْ يُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ بِعَرَضٍ مِنَ الدُّنْيَا","b":"muslim","k":"118","gr":"صحيح","en":"\"Hasten to do good deeds before trials like pieces of the dark night, in which a man will be a believer in the morning and a disbeliever in the evening, or a believer in the evening and a disbeliever in the morning, selling his religion for a trifle of this world.\""},"bunyan":{"id":"bunyan","t":"المؤمن للمؤمن كالبنيان","x":"إِنَّ الْمُؤْمِنَ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا \". وَشَبَّكَ أَصَابِعَهُ","b":"bukhari","k":"481","gr":"صحيح","en":"\"The believer to the believer is like a building, each part strengthening the other,\" and he interlaced his fingers."},"tawadd":{"id":"tawadd","t":"مثل المؤمنين في توادهم وتراحمهم","x":"مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى","b":"muslim","k":"2586","gr":"صحيح","en":"\"The likeness of the believers in their mutual love, mercy and compassion is that of the body: when one limb complains, the whole body responds with sleeplessness and fever.\""},"haja":{"id":"haja","t":"من كان في حاجة أخيه","x":"الْمُسْلِمُ أَخُو الْمُسْلِمِ لاَ يَظْلِمُهُ وَلاَ يُسْلِمُهُ مَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ فِي حَاجَتِهِ وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللَّهُ عَنْهُ بِهَا كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللَّهُ يَوْمَ الْقِيَامَةِ","b":"muslim","k":"2580","gr":"صحيح","en":"\"A Muslim is the brother of a Muslim: he does not wrong him and does not abandon him. Whoever is in the need of his brother, Allah is in his need; whoever relieves a Muslim of a distress, Allah will relieve him by it of a distress of the Day of Resurrection; and whoever covers a Muslim, Allah will cover him on the Day of Resurrection.\""},"dalla":{"id":"dalla","t":"من دلّ على خير فله مثل أجر فاعله","x":"جَاءَ رَجُلٌ إِلَى النَّبِيِّ صلى الله عليه وسلم فَقَالَ إِنِّي أُبْدِعَ بِي فَاحْمِلْنِي فَقَالَ \" مَا عِنْدِي \" . فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم \" مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ","b":"muslim","k":"1893","gr":"صحيح","en":"A man came to the Prophet ﷺ and said: \"My mount has been exhausted, so carry me.\" He said: \"I have nothing.\" A man said: \"O Messenger of Allah, I will direct him to one who will carry him.\" The Messenger of Allah ﷺ said: \"Whoever guides to good has the like of the reward of its doer.\""},"huda":{"id":"huda","t":"من دعا إلى هدى","x":"مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لاَ يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا وَمَنْ دَعَا إِلَى ضَلاَلَةٍ كَانَ عَلَيْهِ مِنَ الإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لاَ يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا","b":"muslim","k":"2674","gr":"صحيح","en":"\"Whoever calls to guidance will have a reward like the rewards of those who follow him, without that diminishing their rewards in the least; and whoever calls to misguidance will bear a sin like the sins of those who follow him, without that diminishing their sins in the least.\""},"ghayyir":{"id":"ghayyir","t":"تغيير المنكر باليد واللسان والقلب","x":"مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ وَذَلِكَ أَضْعَفُ الإِيمَانِ","b":"muslim","k":"49","gr":"صحيح","en":"\"Whoever of you sees a wrong, let him change it with his hand; if he cannot, then with his tongue; and if he cannot, then with his heart, and that is the weakest of faith.\""},"safina":{"id":"safina","t":"مثل القائم على حدود الله والواقع فيها","x":"مَثَلُ الْقَائِمِ عَلَى حُدُودِ اللَّهِ وَالْوَاقِعِ فِيهَا كَمَثَلِ قَوْمٍ اسْتَهَمُوا عَلَى سَفِينَةٍ، فَأَصَابَ بَعْضُهُمْ أَعْلاَهَا وَبَعْضُهُمْ أَسْفَلَهَا، فَكَانَ الَّذِينَ فِي أَسْفَلِهَا إِذَا اسْتَقَوْا مِنَ الْمَاءِ مَرُّوا عَلَى مَنْ فَوْقَهُمْ فَقَالُوا لَوْ أَنَّا خَرَقْنَا فِي نَصِيبِنَا خَرْقًا، وَلَمْ نُؤْذِ مَنْ فَوْقَنَا. فَإِنْ يَتْرُكُوهُمْ وَمَا أَرَادُوا هَلَكُوا جَمِيعًا، وَإِنْ أَخَذُوا عَلَى أَيْدِيهِمْ نَجَوْا وَنَجَوْا جَمِيعًا","b":"bukhari","k":"2493","gr":"صحيح","en":"\"The likeness of one who upholds the limits of Allah and one who transgresses them is like a people who cast lots for a ship: some got its upper deck and some its lower. Those on the lower deck, when they drew water, would pass by those above them, and they said: \"If we made a hole in our share and did not harm those above us.\" If they leave them to what they intend, all will perish; but if they take them by the hand, they will be saved, and all will be saved.\""},"masjid":{"id":"masjid","t":"من بنى مسجداً يبتغي به وجه الله","x":"مَنْ بَنَى مَسْجِدًا ـ قَالَ بُكَيْرٌ حَسِبْتُ أَنَّهُ قَالَ ـ يَبْتَغِي بِهِ وَجْهَ اللَّهِ، بَنَى اللَّهُ لَهُ مِثْلَهُ فِي الْجَنَّةِ","b":"bukhari","k":"450","gr":"صحيح","en":"\"Whoever builds a mosque — Bukayr said: I think he said — seeking by it the face of Allah, Allah will build for him the like of it in Paradise.\""}},"nay":47,"nq":38,"nh":11};
